#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <math.h>

#include <cute/tensor.hpp>

using namespace cute;

template <typename T, int Vec>
__global__ void gelu_kernel(const T* __restrict__ X,
                             T* __restrict__ Y,
                             int64_t N)
{
  const int64_t threads_total = (int64_t)gridDim.x * blockDim.x;
  const int64_t stride = threads_total * Vec;
  const int64_t tid = (int64_t)(blockIdx.x * blockDim.x + threadIdx.x);
  for (int64_t base = tid * Vec; base < N; base += stride) {
    const int64_t remaining = N - base;
    const int n_valid = (int)(remaining < Vec ? remaining : (int64_t)Vec);
    float vals[Vec];
    if (n_valid == Vec) {
      // Fully aligned & contiguous: vectorized 16B loads (float4) in groups of 4
      #pragma unroll
      for (int v = 0; v < Vec; v += 4) {
        float4 f = *reinterpret_cast<const float4*>(X + base + v);
        vals[v + 0] = f.x; vals[v + 1] = f.y; vals[v + 2] = f.z; vals[v + 3] = f.w;
      }
    } else {
      #pragma unroll
      for (int i = 0; i < Vec; ++i) {
        vals[i] = (i < n_valid) ? (float)X[base + i] : 0.0f;
      }
    }
    const float c0 = 0.5f;
    const float c1 = 0.7978845608028654f; // sqrt(2/pi)
    const float c2 = 0.044715f;
    #pragma unroll
    for (int i = 0; i < Vec; ++i) {
      float x  = vals[i];
      float x3 = x * x * x;
      float inner = c1 * (x + c2 * x3);
      // Fast tanh via __expf intrinsic (fast-math friendly, avoids costly tanhf)
      float e2x = __expf(2.0f * inner);
      float t = __fdividef(e2x - 1.0f, e2x + 1.0f);
      vals[i] = c0 * x * (1.0f + t);
    }
    if (n_valid == Vec) {
      // Fully aligned & contiguous: vectorized 16B stores (float4) in groups of 4
      #pragma unroll
      for (int v = 0; v < Vec; v += 4) {
        float4 out;
        out.x = vals[v + 0]; out.y = vals[v + 1]; out.z = vals[v + 2]; out.w = vals[v + 3];
        *reinterpret_cast<float4*>(Y + base + v) = out;
      }
    } else {
      #pragma unroll
      for (int i = 0; i < Vec; ++i) {
        if (i < n_valid) {
          Y[base + i] = (T)vals[i];
        }
      }
    }
  }
}
torch::Tensor gelu_cute_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);
  int64_t N = x_c.numel();
  constexpr int Vec = 8;
  constexpr int Threads = 512;
  int64_t n_vec_threads = (N + Vec - 1) / Vec;
  int64_t blocks = (n_vec_threads + Threads - 1) / Threads;
  if (blocks < 1) blocks = 1;
