  // while keeping enough blocks resident for full occupancy on modern GPUs.
  const int64_t max_blocks = 132 * 32; // heuristic cap (~ SM count * blocks/SM)
  if (blocks > max_blocks) blocks = max_blocks;
  dim3 grid((unsigned int)blocks);
  dim3 block(Threads);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gelu_kernel<float, Vec><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      N
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "gelu_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

gelu_ext = load_inline(
    name="cute_gelu_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["gelu_cute_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include",
                          "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    GELU (tanh approximation) implemented as a single fused CUTE/CUDA kernel.
    """
    def __init__(self) -> None:
        super(ModelNew, self).__init__()
        self._ext = gelu_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.gelu_cute_forward(x)

